function setup() {
  createCanvas(1024, 768, WEBGL);
  noStroke();
  fill(255);
  sphereDetail(5);
}

function draw() {
  background(0);
  lights(); 

  /*// text 
  fill(255);
  text("Click mouse to start fireworks. Hold any key for spheres.", 22, 22);*/

  // manage sparks
  if (keyPressed) {
    noStroke();
  }
  for (let Spark of sparks) {
    Spark.move();
    Spark.display();
    Spark.script();
  }

  // remove dead ones 
  for (i=sparks.size()-1; i>=0; i--) {
    let s = sparks.get(i); 
    if (s.isDead) 
      sparks.remove(i);
  }

  // spawn new 
  if (frameCount%divider == 0) {
    mousePressedNew();
    divider=int(random(13, 33));
  }

  // images for movie (menu tools)
  if (videoExportIsOn1) {
    // let each frame as line-000001.png, line-000002.png, etc.
    saveFrame("line-######.png");
  }
}

