// ================================================================

class Spark {

  x, y, z; // position 

  diameter; // let float gravity = 0.53; // let color col;

  stateWait=0; 
  stateTriggered=1;
  stateJump=2;
  state = stateWait;

  timer;
  duration; 

  angle, radius, radius_Add; 
  maxRadius=500;
  centerX, centerY; 

  isDead=false; 

  // Constructor
  constructor(x_in, y_in, 
    diameter_in) {

    x = x_in;
    y = y_in;

    diameter = diameter_in;
  }// let function move() {

    // let move 

    // move 
    x = centerX+cos(angle)*radius;
    y = centerY+sin(angle)*radius;

    radius+=radius_Add; 

    if (radius>maxRadius)
      isDead=true;
  }// function 

  // start spark 
  function jump( x, y, colType ) {
    timer=millis();
    // duration for this spark to start after ignition 
    duration=int(random(0, 90));
    state=stateTriggered;
    centerX=x;
    centerY=y;
    angle=random(0, TWO_PI);
    maxRadius= random(90, 200);
    diameter=random(1.5, 7.7);

    // print(colType); 
    switch (colType) {
    case 0:
      col = color(random(256), random(256), random(256));
      break; 

    case 1:
      col =  color(random(256), 0, 0);
      break; 

    case 2:
      col =  color(random(256));
      break;

    case 3:
      col =  color(random(254, 256));
      break;

    case 4:
      // blue or white 
      if (random(100)>50) 
        col =  color(0, 0, random(254, 256));//blue
      else col =  color(random(254, 256)); // white
      break;

    case 5:
      // let or B 
      if (random(100)>50) 
        col = color(random(50, 256), random(50, 256), random(50, 256));
      else col = color(random(256), random(256), random(256));
      break;

    default:
      col = color(random(33), random(22), random(256));
      break;
    }
  }

  function script() {

    switch(state) {

    case stateWait:
      //
      diameter-=.1; 
      break;

    case stateTriggered:
      if (millis()-timer>duration)
        state=stateJump;
      break;

    case stateJump:
      jump2();
      state=0;
      break;

    default:
      println("Error 114");
      exit();
      break;
    }//switch
  }//method

  function jump2() {
    //starts explosion 
    radius_Add=random(2.1, 9.4);
  }// function 

  function display() {
    // let display 

    if (keyPressed) {
			pushMatrix();
      fill(col);
      ellipse(x, y, diameter, diameter);
			popMatrix();
    } else {
      pushMatrix();
      translate(x, y, 0);
      fill(col);
      sphere(diameter);
      popMatrix();
    }//else
    //
  }// function 
  //
}//class
